async (page) => {
 const results=[];
 const open=async name=>page.getByRole('button',{name,exact:true}).click();
 const submit=async()=>{await page.locator('#action-form button[type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'});};
 const reset=async()=>{await page.locator('[data-role=dispatch]').first().click();await page.locator('[data-action=qa]').first().click();await open('重置全部演示数据');await submit();await page.locator('[data-role=dispatch]').first().click();};
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1100});await reset();
 for(let i=0;i<2;i++){await open('新建订单');for(const [k,v] of Object.entries({customer:'分页演示客户 '+i,destination:'金边演示收货点',cargo:'演示纸箱',qty:'1',weight:'10',length:'20',width:'20',height:'20',amount:'12'}))await page.locator(`[name=${k}]`).fill(v);await page.locator('#action-form button[type=submit]').click();if(!await page.locator('#action-form button[type=submit]').isDisabled())throw new Error('Submitting state missing');await page.locator('#dialog').waitFor({state:'hidden'});}
 await page.getByRole('button',{name:'下一页',exact:true}).click();if(await page.locator('tbody tr').count()!==1)throw new Error('Pagination wrong');await page.getByRole('button',{name:'上一页',exact:true}).click();if(await page.locator('tbody tr').count()!==4)throw new Error('Pagination return wrong');results.push('分页 5 条 / 4+1、提交中防重复 PASS');
 await open('编辑草稿');await page.locator('[name=payment]').focus();await page.keyboard.press('ArrowDown');await page.keyboard.press('Enter');if(await page.locator('[name=payment]').inputValue()!=='transfer')throw new Error('Native select keyboard failed');await page.getByRole('button',{name:'关闭对话框'}).click();if(!await page.locator('#dialog').isVisible())throw new Error('Dirty form silently discarded');await page.getByRole('button',{name:'关闭对话框'}).click();results.push('原生选择器键盘、脏表单离开确认 PASS');
 await reset();await page.locator('[data-role=finance]').first().click();await open('核验收款');await page.locator('[name=amount]').fill('10');await page.locator('[name=evidence]').fill('DEMO-DIFFERENCE');await submit();await page.locator('[data-tab=finance]').click();if(!(await page.locator('.detail-body').innerText()).includes('金额不符'))throw new Error('Discrepancy not visible');results.push('财务金额差额保持开放 PASS');
 await reset();await page.setViewportSize({width:1280,height:900});if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('1280 overflow');await page.setViewportSize({width:390,height:844});if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('390 desktop overflow');results.push('1280 / 390 管理端局部表格滚动 PASS');
 await page.setViewportSize({width:1440,height:1100});await open('选择车辆并派单');await page.locator('[name=vehicle][value=V01]').check();await submit();await page.locator('[data-role=driver]').first().click();await page.setViewportSize({width:390,height:844});await page.waitForTimeout(4600);await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/driver-action.png',fullPage:true});
 await page.evaluate(()=>{const nodes=[...document.querySelectorAll('.driver-body,.driver-body *')];const sizes=nodes.map(n=>parseFloat(getComputedStyle(n).fontSize));nodes.forEach((n,i)=>n.style.fontSize=sizes[i]*2+'px');});if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('Driver enlarged text overflow');results.push('司机内容文字放大 200% 无横向溢出 PASS');
 await page.reload();await page.setViewportSize({width:1440,height:1100});await reset();return {browser:'PASS',checks:results};
}
